        username = user.key.split('/')[2]

        def response(msg, status="success"):
            return delegate.RawText(
                json.dumps({status: msg}), content_type="application/json"
            )

        if i.notes is None:
            Booknotes.remove(username, work_id, edition_id=edition_id)
